age; 272-row CSV."}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:PLACEBO_DEPENDENCE"}]}, {"id": "FAM:SF-APPA-050", "label": "Study family SF-APPA-050: Superstar sequential suppression: opponent play before the star", "score": 0.765, "reached_via": ["FAM:SF-APPM-022 auto_related_family (repeated_by_later_family) FAM:SF-APPA-050", "FAM:SF-APPM-022 auto_related_family (repeat_of_earlier_family) FAM:SF-APPA-050"], "attributes": {"observed_research_question": "Superstar sequential suppression: opponent play before the star", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "A specific opponent play type on the preceding possession suppresses each star's next-possession PPP relative to that star's baseline.", "observed_result": "PUTBACK is top suppressor for 6+ stars (e.g. D. Mitchell 1.178 to 0.884, d=-0.294, n_after=95; B. Beal d=-0.345 n=32; C. Holmgren d=-0.222 n=52). Other tops: TRANSITION (A. Davis -0.058), POST_UP (N. Jokic -0.075), PULL_ [cut; read_family for the full text]", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No multiplicity correction; n_after is 32-95 for several PUTBACK cells vs thousands of baseline possessions.", "observed_sample_and_power": "30 stars; min n_after=30", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED"}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:DRIFT_NONSTATIONARITY"}]}, {"id": "FAM:SF-APPM-022", "label": "Study family SF-APPM-022: Superstar suppression profiles (incl. Q5c sequential triggering)", "score": 0.765, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPM-022 (0.77)"], "attributes": {"observed_research_question": "Superstar suppression profiles (incl. Q5c sequential triggering)", "auto_outcome_status": "inconclusive", "observed_hypothesis": "Specific opposing lineups, defenders, play types and preceding opponent play types suppress star efficiency.", "observed_result