el": "Study family SF20: Absence validation (structure moves under real absence; simulation tracks it)", "score": 0.639, "reached_via": ["FAM:SF17 auto_related_family (record_link_related_to) FAM:SF20", "request matches DS:Player_absence_spells (0.77); FAM:SF20 auto_uses_dataset DS:Player_absence_spells"], "attributes": {"observed_research_question": "Absence validation (structure moves under real absence; simulation tracks it)", "auto_outcome_status": "untestable", "observed_hypothesis": "Real player absences move the association structure (V1) and the LOO simulation predicts the magnitude (V2).", "observed_result": ["[APPA-006] Gate G2 21/23 (91%) above null median; V1(a) 16/23 above own-null p95, binomial p=2.67e-16; V1(b) mean(D_real - median_null)=+0.142, CI [+0.103, +0.187].", "[APPA-007] Gate G3 Spearman +0.099. V2a Spearman +0.288, p=0.077, CI [-0.244, +0.667] FAIL; V2b partial +0.253, p=0.115, CI [-0.262, +0.615] FAIL. Diagnostics: H_code ruled out (rho=0.933); dropping 2 absorption cases rh [cut; read_family for the full text]", "[PAP-023] V1(a) 16/23 above p95 binomial p=2.67e-16; V1(b) +0.142 CI[+0.103,+0.187] CONFIRMED; V2a rho=+0.288 p=0.077 CI[-0.244,+0.667]; V2b rho=+0.253 p=0.115 NOT"]}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:small_sample"}]}, {"id": "FAM:SF-PAP-014", "label": "Study family SF-PAP-014: On/off identity displacement D_A (shaper vs usage-matched role occupant)", "score": 0.609, "reached_via": ["request matches RQC:RQC-013 (0.81); FAM:SF-PAP-014 auto_addresses_question RQC:RQC-013", "request matches DS:Player_absence_spells (0.77); FAM:SF-PAP-014 auto_uses_dataset DS:Player_absence_spells"], "attributes": {"observed_research_question": "On/off identity displacement D_A (shaper vs usage-matched role occupant)", "auto_outcome_status": "supported", "observed_hypothesis": "Real on/off absence of a shaper displaces the team fingerprint more than a usage-matched non-shaper, and LOO L(p) tracks observed D_A.", "observed_result": "Delta D_A=+0.115, t=6.35, p~7e-9, shaper larger in 81% of pairs; Delta D_pi=+0.011 p~1e-4; r(L,D_A)=+0.60 (shapers +0.79)", "auto_failure_mechanism": "D_positive (no failure: positive result)", "observed_failure_evidence": "t=6.35 on 96 pairs", "observed_sample_and_power": "n=908; 96 pairs", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "908 player-seasons with >=400 poss on and off; 96 usage-matched pairs (caliper 0.03); correlation of L with D_A.", "observed_verdict": "supported"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPS-088"}, {"rel": "auto_related_family", "node": "FAM:SF-PAP-011"}, {"rel": "auto_related_family", "node": "FAM:SF-PAP-028"}]}, {"id": "FAM:SF-APPS-087", "label": "Study family SF-APPS-087: Connector tangible impact: star shielding, TO, lineup lift", "score": 0.494, "reached_via": ["request matches RQC:RQC-123 (0.78); FAM:SF-APPS-087 auto_addresses_question RQC:RQC-123"], "attributes": {"observed_research_question": "Connector tangible impact: star shielding, TO, lineup lift", "auto_outcome_status": "rejected", "observed_hypothesis": "Connector presence shields stars (higher TS, lower TO) and lifts lineup ORtg beyond talent.", "observed_result": "Star dTS +0.05 pp p=0.937; dTO +0.74 pp p=0.00364 (wrong sign for shielding). Star-init TO~HasConn beta=+0.34 pp p=0.439. HasConn on-off PPP BOTH_NULL (mean -0.041 p=0.939, median +0.528 p=0.731, n=73). Frequent-conn lin [cut; read_family for the full text]", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "PPP/TS/eFG shielding null; TO rate rises with connectors. Lineup ORtg lift is a talent confound (p=0.51 after TALENT; swap p=0.565).", "observed_verdict": "null"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:confounding"}, {"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:CONFOUNDING"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}, {"rel": "auto_related_family", "node": "FAM:SF-APPS-086"}]}, {"id": "FAM:SF-PAP-030", "label": "Study family SF-PAP-030: Defensive reorganizer on/off: opponent fingerprint vs PPP allowed", "score": 0.492, "reached_via": ["request matches RQC:RQC-154 (0.78); FAM:SF-PAP-030 auto_addresses_question RQC:RQC-154"], "attributes": {"observed_research_question": "Defensive reorganizer on/off: opponent fingerprint vs PPP allowed", "auto_outcome_status": "rejected", "observed_hypothesis": "Defenders who displace the opponent's initiation fingerprint (high D_A) also suppress opponent PPP.", "observed_result": "eligible 653/882; corr(D_A, n_on) all=-0.475 vs eligible=-0.036; eligible median D_A=0.0529, median dPPP_allowed=-0.298; corr(D_A, dPPP_allowed)=+0.020; quadrants ~161-166 each", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "among 653 eligible, corr(D_A, dPPP_allowed)=+0.020; high-D_A names (Isaiah Joe 0.168, Trey Lyles 0.157) often allow more PPP", "observed_sample_and_power": "n=653 eligible of 882", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "null", "observed_failure_type": "B_powered_null"}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:MECHANICAL_FLOOR"}, {"rel": "auto_related_family", "node": "FAM:SF-PAP-014"}]}], "n_results": 10}

